const settings = $input.first().json || {};
let id = String(settings['seo.ga4_property_id'] || '').trim();
id = id.replace(/^properties\//i, '').replace(/\D/g, '');
if (!id) {
  return [];
}
return [{ json: { property_id: id } }];

function metricMap(row, headers) {
  const out = {};
  const metrics = row.metricValues || [];
  (headers || []).forEach((h, i) => {
    const name = h.name || h;
    const n = Number(metrics[i] && metrics[i].value);
    out[name] = Number.isFinite(n) ? n : 0;
  });
  return out;
}
function dimMap(row, headers) {
  const out = {};
  const dims = row.dimensionValues || [];
  (headers || []).forEach((h, i) => {
    out[h.name || h] = String((dims[i] && dims[i].value) || '');
  });
  return out;
}
function googleErr(raw) {
  if (!raw || typeof raw !== 'object') return true;
  if (raw.error || raw.error_code || raw.message && !raw.metricHeaders && !raw.dimensionHeaders) return true;
  return false;
}
const prop = $('Property id').first().json || {};
const channelsRaw = $('Channel mix').first().json || {};
const landingsRaw = $('Organic landings').first().json || {};
if (googleErr(channelsRaw) || googleErr(landingsRaw)) {
  return [];
}
const channels = [];
let sessions = 0;
let organic = 0;
for (const row of (channelsRaw.rows || [])) {
  const d = dimMap(row, channelsRaw.dimensionHeaders || []);
  const m = metricMap(row, channelsRaw.metricHeaders || []);
  const name = d.sessionDefaultChannelGroup || '(other)';
  const s = m.sessions || 0;
  sessions += s;
  if (name === 'Organic Search') organic = s;
  channels.push({ name: name, sessions: s, engaged_sessions: m.engagedSessions || 0, bounce_rate: m.bounceRate || 0 });
}
const landing_pages = [];
for (const row of (landingsRaw.rows || []).slice(0, 15)) {
  const d = dimMap(row, landingsRaw.dimensionHeaders || []);
  const m = metricMap(row, landingsRaw.metricHeaders || []);
  landing_pages.push({ path: d.landingPagePlusQueryString || '/', sessions: m.sessions || 0, engagement_rate: m.engagementRate || 0 });
}
return [{ json: {
  source: 'ga4_data_api',
  property_id: String(prop.property_id || ''),
  range: '28daysAgo:yesterday',
  fetched_at: new Date().toISOString(),
  sessions: sessions,
  organic_sessions: organic,
  channels: channels,
  landing_pages: landing_pages
} }];
